{
  "county_id": "HVA04",
  "actions": [
    {
      "action_id": "self-sampling",
      "action": "Mail an HPV self-sampling kit with the second reminder to everyone invited to cervical screening who has not attended.",
      "rationale": "Cervical screening participation in Vantaa and Kerava wellbeing services county is 70.1% against the 80% target, and the model scenario expects self-sampling kits for non-attenders to add 1.5-4.5 percentage points, closing about 30% of the gap.",
      "owner_role": "Wellbeing services county screening unit",
      "indicator": "Proportion of women invited to cervical cancer screening (smear test) who attended, %",
      "roadmap_measure": "2.4.4"
    },
    {
      "action_id": "screening-reminders",
      "action": "Send a second colorectal screening kit with plain-language, multilingual instructions to non-responders and measure the gain as a stepped pilot.",
      "rationale": "Colorectal screening participation in Vantaa and Kerava wellbeing services county is 72.7% against the 80% target, and the model scenario expects reminders and multilingual re-invitation to add 1.5-4.5 percentage points, closing about 41% of the gap.",
      "owner_role": "Wellbeing services county screening unit",
      "indicator": "Proportion of invited to colorectal cancer screening who attended, %",
      "roadmap_measure": "1.3.1"
    },
    {
      "action_id": "pathway-timestamps",
      "action": "Add first contact, referral, diagnosis and first treatment dates, plus entry route, to the national cancer quality register and publish county-level medians quarterly.",
      "rationale": "Time from referral to diagnosis and from diagnosis to first treatment is not published by county for any cancer, so the Goal 3 indicator that patients access treatment within established target times cannot be checked from open data in Vantaa and Kerava wellbeing services county.",
      "owner_role": "FICAN with THL and the Finnish Cancer Registry",
      "indicator": "Share of new cancer cases with all four timestamps recorded",
      "roadmap_measure": "3.2.1"
    }
  ],
  "evidence_does_not_support": "The evidence does not support a guaranteed mortality effect: the Finnish gain of self-sampling over a reminder letter is about 3 points, far smaller than the international pooled estimate, no Finnish effect size exists for colorectal reminders, and the timestamp action models no health effect because it is only the measurement that makes other actions accountable."
}

